function avatar(i,small=false){return `<span class="avatar a${i} ${small?'tiny':''}" aria-hidden="true"></span>`}
function brand(){return `<div class="brand">${icon('book')}<span>City University of Hong Kong</span></div>`}
function selectPage(){clearGirl();stopAudio();clearInterval(tick);session=false;app.className='';app.innerHTML=`<header>${brand()}<nav class="steps" aria-label="Learning steps"><span class="active"><b>1</b>Choose an advisor</span><i></i><span><b>2</b>Start talking</span></nav></header><main class="choose"><div class="intro"><h1>Welcome to Academic Advisory Portal</h1><p>Choose your academic advisor to begin your session.</p></div><div class="cards">${advisors.map((a,i)=>`<button class="advisor ${selected===i?'selected':''}" aria-pressed="${selected===i}" data-select="${i}">${selected===i?`<span class="selection">${icon('check')}</span>`:''}<div class="avatar a${i}" aria-hidden="true"></div><h2>${a.name}</h2></button>`).join('')}</div><div class="start"><button class="primary" id="start">${icon('mic')}Start Session</button><p class="fine">Speak at your own pace. You can also type your answers.</p></div><p class="demo">Interactive preview · Browser voice</p></main>`;document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=+b.dataset.select;selectPage();$(`[data-select="${selected}"]`).focus()});$('#start').onclick=startSession;document.title='Academic Advisory Portal · City University of Hong Kong'}
function startSession(){clearGirl();stopAudio();session=true;ended=false;phase='survey';turns=0;answered=null;transcript=[];caption=true;historyOpen=true;started=Date.now();app.className='session';const a=advisor();app.innerHTML=`<header>${brand()}<div class="header-advisor">${avatar(selected,true)}<span>${a.name}</span></div><div class="topic">Academic Advisory Portal</div><button id="end" class="danger">${icon('end')}End conversation</button></header><main class="workspace"><section class="main-column" aria-label="Conversation with ${a.name}"><div class="advisor-label"><span>Academic Advisor</span><strong>${a.name}</strong></div><div class="stage ${advisor().model?'girl-stage':selected===1?'other':''}">${advisor().model?`<div class="girl-character"><img class="girl-poster" src="assets/${a.model}/portrait.png" alt="${a.name} virtual avatar"><canvas id="girl-canvas" aria-label="Animated ${a.name} avatar"></canvas></div>`:''}<div class="scene" role="img" aria-label="${a.name} in a calm classroom"></div>${selected===1&&!advisor().model?`<div class="hero-avatar avatar a${selected}" aria-hidden="true"></div>`:''}<div class="presence"><span class="dot"></span><span id="presence-text">${a.name} · Ready</span></div><div class="timer">${icon('clock')}<span id="time">00:00</span></div><div class="subtitle voice-bubble" id="subtitle" data-state="idle"><div class="voice-visual"><div class="live-wave" aria-hidden="true">${Array.from({length:39},(_,i)=>`<i style="--bar-height:${[12,20,34,48,29,17,39,54,25][i%9]}px;--delay:${-(i%11)*.11}s"></i>`).join('')}</div><div class="thinking-dots" aria-hidden="true"><i></i><i></i><i></i></div></div><div class="voice-copy" aria-live="polite" aria-atomic="true"><p id="voice-label">Ready to talk</p><p id="voice-hint">Start speaking when you are ready.</p></div></div><section class="quiz" id="quiz" aria-label="Multiple-choice question" hidden></section><div class="summary" id="summary" hidden></div></div><div class="controls"><button class="primary" id="mic">${icon('mic')}Start speaking</button><button class="secondary history-toggle" id="show-history" aria-expanded="true">${icon('history')}History</button></div><p class="status" id="status" role="status">You can speak or type your answer.</p><form class="text-form" id="reply"><input id="answer-text" aria-label="Your answer" placeholder="Or type your answer…" maxlength="600" autocomplete="off"><button class="secondary" aria-label="Send answer">${icon('send')}Send</button></form><p class="demo">Guided session preview · No live AI connection</p></section><aside class="history" aria-label="Conversation history"><div class="history-top"><h2>${icon('history')}Chat history</h2><button id="hide-history" class="icon-button" aria-label="Hide conversation history">${icon('close')}</button></div><label class="search">${icon('search')}<input id="search" type="search" placeholder="Search conversation" aria-label="Search conversation"></label><div class="messages" id="messages" role="log" aria-label="Conversation messages"></div><button class="secondary latest" id="latest">${icon('down')}Back to latest</button><p class="history-note">Available during this session only</p></aside><aside class="survey" aria-label="General health survey"><div class="survey-heading">General health survey <span>3 minutes</span></div><p class="survey-intro">Let's go through a survey of your general health. It only takes 3 minutes and we can continue our conversation as soon as you complete this survey.</p><div class="survey-progress"><span>Question</span><strong>3/12</strong></div><div class="progress-track" aria-hidden="true"><i></i></div><fieldset id="health-options"><legend>Have you recently been able to concentrate on whatever you're doing?</legend>${healthOptions.map((option,i)=>`<label class="health-option"><input type="radio" name="concentration" value="${i}"><span>${option}</span></label>`).join('')}</fieldset><p id="survey-status" role="status">Choose the response that best describes your experience.</p><button class="primary" id="confirm-survey" disabled>Confirm response ${icon('arrow')}</button><p class="survey-note">Preview of question 3. Remaining questions are not yet available. Your response stays in this session.</p></aside></main><dialog id="end-dialog"><h2>Finish for now?</h2><p>You can still read your conversation history after ending this session.</p><div class="dialog-actions"><button class="secondary" id="cancel-end">Keep talking</button><button class="danger" id="confirm-end">End conversation</button></div></dialog>`;
$('#end').onclick=()=>{stopAudio();$('#end-dialog').showModal()};$('#cancel-end').onclick=()=>$('#end-dialog').close();$('#confirm-end').onclick=()=>{$('#end-dialog').close();finish()};$('#mic').onclick=listen;$('#reply').onsubmit=e=>{e.preventDefault();submit($('#answer-text').value)};$('#search').oninput=()=>renderHistory(false);$('#latest').onclick=()=>{$('#search').value='';renderHistory(true)};$('#hide-history').onclick=()=>toggleHistory(false);$('#show-history').onclick=()=>{toggleHistory(!historyOpen);if(historyOpen)document.querySelector('.history').scrollIntoView({block:'nearest'})};clearInterval(tick);tick=setInterval(()=>{if(!session||ended)return;const seconds=Math.floor((Date.now()-started)/1000);$('#time').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')},1000);document.querySelectorAll('[name=concentration]').forEach(r=>r.onchange=()=>{$('#confirm-survey').disabled=false;document.querySelectorAll('.health-option').forEach(l=>l.classList.toggle('selected',l.querySelector('input').checked))});$('#confirm-survey').onclick=confirmSurvey;if(advisor().model)girlReady=mountGirl();say(surveyIntro);document.title='Academic Advisory Session · City University of Hong Kong'}
function toggleHistory(open){historyOpen=open;app.classList.toggle('history-hidden',!open);$('#show-history').setAttribute('aria-expanded',String(open))}
function message(who,text){transcript.push({who,text,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});renderHistory(true)}
function renderHistory(scroll){const query=$('#search').value.toLowerCase().trim();const filtered=transcript.map((m,i)=>({...m,i})).filter(m=>m.text.toLowerCase().includes(query)||(m.who==='user'?'you':advisor().name.toLowerCase()).includes(query));$('#messages').innerHTML=filtered.length?filtered.map(m=>`<article class="message ${m.who==='user'?'user':''}">${m.who==='user'?`<span class="user-icon">${icon('user')}</span>`:avatar(selected,true)}<div class="message-body"><div class="message-meta"><strong>${m.who==='user'?'You':advisor().name}</strong><time>${m.time}</time></div><div class="voice-message"><button class="audio-play" data-replay="${m.i}" aria-label="Read message ${m.i+1} aloud">${icon('speaker')}</button><div class="sound-wave" aria-hidden="true">${Array.from({length:19},(_,i)=>`<i style="height:${[9,17,26,14,31,22,12][i%7]}px"></i>`).join('')}</div></div><button class="text-toggle" data-text="${m.i}" aria-expanded="${!!query}" aria-controls="message-text-${m.i}">${query?'Hide text':'Show text'}</button><p class="transcript-text" id="message-text-${m.i}" ${query?'':'hidden'}>${esc(m.text)}</p></div></article>`).join(''):'<p class="no-results">No matching messages. Try a different word.</p>';document.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.voice-message').forEach(n=>n.classList.remove('playing'));b.closest('.voice-message').classList.add('playing');speak(transcript[+b.dataset.replay].text)});document.querySelectorAll('[data-text]').forEach(b=>b.onclick=()=>{const p=$('#message-text-'+b.dataset.text);p.hidden=!p.hidden;b.textContent=p.hidden?'Show text':'Hide text';b.setAttribute('aria-expanded',String(!p.hidden))});if(scroll&&!query)$('#messages').scrollTop=$('#messages').scrollHeight}
function status(text){if($('#status'))$('#status').textContent=text}
function setVoiceState(next){voiceState=next;const bubble=$('#subtitle');if(!session||!bubble)return;const copy={idle:['Ready to talk','Start speaking when you are ready.'],requesting:['Connecting microphone…','Please allow microphone access.'],listening:['I’m listening…','Speak naturally. Pause when you’ve finished.'],processing:['One moment…',advisor().name+' is preparing a reply.'],speaking:[advisor().name.replace(/^Mr /,'Mr. ')+' Speaking…',''],muted:['Microphone muted','Unmute whenever you are ready.'],error:['Microphone unavailable','You can still type your message below.'],ended:['Session ended','']}[next];clearTimeout(fadeTimer);bubble.classList.add('state-changing');fadeTimer=setTimeout(()=>{if(!session||!$('#subtitle'))return;bubble.dataset.state=next;$('#voice-label').textContent=copy[0];$('#voice-hint').textContent=copy[1];bubble.classList.remove('state-changing')},120);voiceUI()}
function voiceUI(){girlAvatar?.setTalking(speaking&&!ended);if(!session||!$('#mic'))return;$('#presence-text').textContent=ended?'Session ended':voiceEnabled?'Live conversation':speaking?'Advisor speaking':'Ready to talk';document.querySelector('.stage').classList.toggle('talking',speaking);$('#mic').innerHTML=icon(voiceEnabled?'pause':'mic')+(voiceEnabled?'Mute mic':voiceState==='muted'?'Unmute mic':'Start speaking');$('#mic').setAttribute('aria-pressed',String(voiceEnabled));$('#mic').disabled=ended||voiceState==='requesting';if(!speaking)document.querySelectorAll('.voice-message').forEach(n=>n.classList.remove('playing'))}
function releaseMic(){cancelAnimationFrame(levelFrame);levelFrame=0;micStream?.getTracks().forEach(t=>t.stop());micStream=null;analyser=null;if(audioContext){audioContext.close().catch(()=>{});audioContext=null}}
function stopAudio(full=true){voiceToken++;girlAvatar?.stopVoice();clearTimeout(playbackTimer);clearTimeout(restartTimer);clearTimeout(replyTimer);window.speechSynthesis?.cancel();if(recognition){recognition.onstart=null;recognition.onend=null;recognition.onerror=null;recognition.onresult=null;recognition.abort();recognition=null}listening=false;speaking=false;if(full){requestVersion++;voiceEnabled=false;releaseMic()}if(session)setVoiceState(ended?'ended':full?'idle':'processing')}
function say(text){last=text;message('advisor',text);speak(text)}
function resumeListening(){clearTimeout(restartTimer);if(voiceEnabled&&!ended&&session)restartTimer=setTimeout(beginRecognition,350);else if(session&&!ended)setVoiceState(voiceState==='muted'?'muted':'idle')}
function speak(text){if(!text)return;stopAudio(false);const token=voiceToken;
 if(advisor().model&&girlReady){status('Preparing voice reply…');girlReady.then(()=>{
  if(token!==voiceToken||ended||!session)return;
  if(!girlAvatar?.hasClip(text)){speakBrowser(text,token);return;}
  const done=()=>{if(token!==voiceToken)return;speaking=false;resumeListening();status(voiceEnabled?'Your turn. Speak naturally.':'Start speaking, or type your message below.');};
  const error=()=>{if(token!==voiceToken)return;girlAvatar.stopVoice();speaking=false;resumeListening();status('Audio could not play. Use the speaker button in history to try again.');};
  girlAvatar.playVoice(text,{start:()=>{if(token!==voiceToken)return;speaking=true;setVoiceState('speaking');status('Your advisor is speaking.');},end:done,error}).catch(error);
 });return;}speakBrowser(text,token);}
function speakBrowser(text,token){if(!('speechSynthesis'in window)){status('Voice playback is not available here. Use Show text in chat history.');resumeListening();return}status('Preparing voice reply…');speech=new SpeechSynthesisUtterance(text);speech.onboundary=()=>{if(token===voiceToken)girlAvatar?.word();};speech.lang='en-GB';speech.rate=.9;const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'));if(voice)speech.voice=voice;speech.onstart=()=>{if(token!==voiceToken)return;clearTimeout(playbackTimer);speaking=true;setVoiceState('speaking');status(voiceEnabled?'Your advisor is speaking. Listening resumes automatically afterwards.':'Your advisor is speaking.')};speech.onend=()=>{if(token!==voiceToken)return;clearTimeout(playbackTimer);speaking=false;if(ended){setVoiceState('ended');return}resumeListening();status(voiceEnabled?'Your turn. Speak naturally.':'Start speaking, or type your message below.')};speech.onerror=()=>{if(token!==voiceToken)return;clearTimeout(playbackTimer);speaking=false;status('Audio could not play. Use Show text or the speaker button in history.');resumeListening()};playbackTimer=setTimeout(()=>{if(token!==voiceToken||speaking)return;voiceToken++;speechSynthesis.cancel();status('Voice playback did not start. Use Show text or the speaker button in history.');resumeListening()},8000);speechSynthesis.speak(speech)}
function drawInputLevel(){if(!analyser||!micStream)return;const buffer=new Uint8Array(analyser.fftSize);const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let smoothed=0;const draw=()=>{if(!analyser||!micStream)return;analyser.getByteTimeDomainData(buffer);let sum=0;for(const value of buffer)sum+=((value-128)/128)**2;const level=Math.min(1,Math.sqrt(sum/buffer.length)*6);smoothed=smoothed*.65+level*.35;const bars=document.querySelectorAll('.live-wave i');bars.forEach((bar,i)=>{const shape=.35+.65*Math.abs(Math.sin(i*.49));bar.style.setProperty('--input-scale',String(reduced.matches?.38:Math.max(.08,smoothed*shape)))});levelFrame=requestAnimationFrame(draw)};draw()}
function beginRecognition(){if(!voiceEnabled||ended||!session||speaking||recognition)return;const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){failMic('Speech recognition is not supported here. Please type below.');return}const token=voiceToken;const r=new R();recognition=r;r.lang='en-GB';r.interimResults=false;r.continuous=false;let received=false;r.onstart=()=>{if(token!==voiceToken)return;listening=true;setVoiceState('listening');status('Listening. Your message is sent automatically when you finish speaking.')};r.onresult=e=>{if(token!==voiceToken||!voiceEnabled||ended||received)return;const result=e.results[e.resultIndex??0];if(!result.isFinal)return;const text=result[0].transcript.trim();if(!text)return;received=true;recognitionFailures=0;submit(text)};r.onerror=e=>{if(token!==voiceToken)return;if(e.error==='no-speech')return;failMic(e.error==='not-allowed'?'Microphone access was not allowed. Allow it in your browser or type below.':'Voice recognition is unavailable. Please try again or type below.')};r.onend=()=>{if(token!==voiceToken)return;listening=false;recognition=null;if(voiceEnabled&&!received&&!ended){recognitionFailures++;if(recognitionFailures>8){failMic('Voice input paused after repeated empty results. Start speaking to reconnect.');return}resumeListening()}};try{r.start()}catch{failMic('Could not start voice recognition. Please type below.')}}
function failMic(text){stopAudio();if(!session||ended)return;setVoiceState('error');status(text)}

function confirmSurvey(){const choice=document.querySelector('[name=concentration]:checked');if(!choice||ended)return;const text=healthOptions[+choice.value];message('user','Question 3: '+text);$('#health-options').disabled=true;$('#confirm-survey').disabled=true;$('#confirm-survey').textContent='Response noted';$('#survey-status').textContent='Your response is noted for this session. The remaining survey questions have not been added to this preview.';phase='conversation';say('Thank you for sharing. This preview contains question 3 only. What would you like to discuss about your studies?')}
function submit(raw){const text=raw.trim();if(!text||ended)return;$('#answer-text').value='';stopAudio(false);if(phase==='survey'){const i=healthOptions.findIndex(o=>o.toLowerCase()===text.toLowerCase().replace(/[.!?]$/,''));if(i>=0){const radio=document.querySelector(`[name=concentration][value="${i}"]`);radio.checked=true;radio.onchange();status('Your response is selected. Choose Confirm response to submit it.');resumeListening();return}}message('user',text);setVoiceState('processing');const token=voiceToken;replyTimer=setTimeout(()=>{if(token!==voiceToken||ended||!session)return;if(phase==='survey'){say('Please choose the response that best describes your experience in the survey panel. You can confirm it when you are ready.')}else{say('Thank you for sharing. Your message is in the chat history. This is a guided preview; a live academic advisor connection has not been added yet.')}},300)}

async function listen(){if(ended)return;if(voiceEnabled){stopAudio();setVoiceState('muted');status('Microphone muted. Unmute to continue.');return}const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R||!navigator.mediaDevices?.getUserMedia){failMic('Voice input is not supported here. Please type your answer below.');return}stopAudio();setVoiceState('requesting');const version=requestVersion;try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});if(version!==requestVersion||ended||!session){stream.getTracks().forEach(t=>t.stop());return}micStream=stream;const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){try{audioContext=new Audio();await audioContext.resume();if(version!==requestVersion||ended||!session){releaseMic();return}analyser=audioContext.createAnalyser();analyser.fftSize=256;audioContext.createMediaStreamSource(stream).connect(analyser);drawInputLevel()}catch{analyser=null;status('Microphone connected. The volume display is unavailable.')}}voiceEnabled=true;recognitionFailures=0;stream.getAudioTracks().forEach(track=>track.onended=()=>{if(voiceEnabled&&!ended)failMic('Microphone disconnected. Reconnect or type your answer below.')});beginRecognition()}catch{if(version===requestVersion&&!ended&&session)failMic('Microphone access was not allowed or is unavailable. Please try again or type below.')}}

function finish(){stopAudio();ended=true;clearInterval(tick);voiceUI();$('#end').disabled=true;$('#mic').disabled=true;$('#health-options').disabled=true;$('#confirm-survey').disabled=true;$('#reply').hidden=true;$('#quiz').hidden=true;$('#subtitle').hidden=true;$('#summary').hidden=false;$('#summary').innerHTML=`<div>${icon('check')}<h2>Thank you for your time!</h2><p>Your session has ended. You can still review the chat history on the left.</p><button class="primary" id="again">Start a new session</button><button class="secondary" id="change">Choose another advisor</button></div>`;$('#again').onclick=startSession;$('#change').onclick=selectPage;status('Session ended. Choose an activity to start again.')}
window.addEventListener('pagehide',()=>{stopAudio();clearInterval(tick);clearTimeout(fadeTimer)});selectPage();
